  "programmatic_capture_profiles": "SELECT r.id::text AS id, r.xmin::text AS row_version, jsonb_build_object('id',r.id,'workspace_id',r.workspace_id,'enabled',r.enabled,'created_by',r.created_by,'created_at',r.created_at,'updated_at',r.updated_at)||jsonb_build_object('intake_binding.actor',r.intake_binding#>'{actor}','intake_binding.policyRevision',r.intake_binding#>'{policyRevision}','intake_binding.sensitivity',r.intake_binding#>'{sensitivity}','intake_binding.compartments',r.intake_binding#>'{compartments}','intake_binding.projectIds',r.intake_binding#>'{projectIds}','intake_binding.visibility',r.intake_binding#>'{visibility}','configuration_bound',r.intake_binding IS NOT NULL,'configuration_expires_at',s.expires_at,'configuration_revoked_at',s.revoked_at) AS metadata FROM programmatic_capture_profiles r LEFT JOIN auth_sessions s ON s.id::text=r.intake_binding->>'session' AND s.user_id::text=r.intake_binding->>'actor' AND EXISTS(SELECT 1 FROM workspace_members m WHERE m.workspace_id=r.workspace_id AND m.user_id=s.user_id) WHERE r.workspace_id=$1",
