  "scope_derivation_sources": "SELECT r.derivation_id::text||':'||r.source_kind||':'||r.source_id::text AS id, r.xmin::text AS row_version, jsonb_build_object('workspace_id',r.workspace_id,'derivation_id',r.derivation_id,'source_kind',r.source_kind,'source_id',r.source_id,'source_version',r.source_version) AS metadata FROM scope_derivation_sources r WHERE r.workspace_id=$1",
